class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        if not nums:
            return 0

        tails = [nums[0]]
        for i in range(1, len(nums)):
            if nums[i] > tails[-1]:
                tails.append(nums[i])
            else:
                idx = self.binary_search(tails, nums[i])
                tails[idx] = nums[i]
        return len(tails)

    def binary_search(self, tails: List[int], target: int) -> int:
        left, right = 0, len(tails) - 1
        while left <= right:
            mid = (left + right) // 2
            if tails[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

