class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        n_squared = n * n
        queue = [(1, 0)]  # (position, steps)
        visited = set([1])

        while queue:
            curr_pos, steps = queue.pop(0)
            if curr_pos == n_squared:
                return steps

            for next_pos in range(curr_pos + 1, min(curr_pos + 6, n_squared) + 1):
                row = (n - 1) - (next_pos - 1) // n
                col = (next_pos - 1) % n
                if board[row][col] != -1:
                    next_pos = board[row][col]

                if next_pos not in visited:
                    queue.append((next_pos, steps + 1))
                    visited.add(next_pos)

