class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        # Create a set of words for O(1) lookups
        word_set = set(wordList)

        # If the endWord is not in the wordList, return 0
        if endWord not in word_set:
            return 0

        # Initialize a queue with the beginWord and a distance of 1
        queue = deque([(beginWord, 1)])

        # Perform BFS
        while queue:
            word, distance = queue.popleft()

            # If the current word is the endWord, return the distance
            if word == endWord:
                return distance

            # Generate all possible transformations of the current word
            for i in range(len(word)):
                for char in 'abcdefghijklmnopqrstuvwxyz':
                    next_word = word[:i] + char + word[i + 1:]

                    # If the next word is in the word set, add it to the queue and remove it from the set
                    if next_word in word_set:
                        queue.append((next_word, distance + 1))
                        word_set.remove(next_word)

        # If no transformation sequence is found, return 0
        return 0

