class Solution:
    def minWindow(self, s: str, t: str) -> str:
        # Base case: If string t is longer than string s or if t is empty, return empty string
        if len(t) > len(s) or not t:
            return ""

        # Create a dictionary to store the frequency of characters in string t
        t_count = {}
        for char in t:
            if char in t_count:
                t_count[char] += 1
            else:
                t_count[char] = 1

        # Initialize variables to keep track of the minimum window
        required_chars = len(t_count)
        formed_chars = 0

        # Initialize the window boundaries
        window_counts = {}
        left = 0
        min_len = float('inf')
        min_window = ""

        # Traverse the string s
        for right in range(len(s)):
            character = s[right]
            window_counts[character] = window_counts.get(character, 0) + 1

            # If the character is in t and its frequency in the window is equal to its frequency in t, increment formed_chars
            if character in t_count and window_counts[character] == t_count[character]:
                formed_chars += 1

            # While the window contains all characters in t and the left boundary is not at the beginning of the string
            while left <= right and formed_chars == required_chars:
                character = s[left]

                # Update the minimum window if the current window is smaller
                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    min_window = s[left:right + 1]

                # Shrink the window from the left
                window_counts[character] -= 1
                if character in t_count and window_counts[character] < t_count[character]:
                    formed_chars -= 1

                # Move the left boundary to the right
                left += 1

        return min_window

