    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        columnTable = {}
        min_column = max_column = 0
        queue = [(root, 0, 0)]

        while queue:
            node, column, row = queue.pop(0)

            if node is not None:
                if column not in columnTable:
