        inversions = 0

        # Count the number of negative numbers
        negative_count = sum(1 for num in seq if num < 0)

        # Sort the modified sequence
        sorted_seq = sorted(modified_seq)

        # Initialize a list to store the positions of elements in the sorted sequence
        pos = [0] * n
        for i in range(n):
            pos[i] = sorted_seq.index(modified_seq[i])
            sorted_seq[pos[i]] = -1  # Mark as visited

        # Calculate the number of inversions
        for i in range(n):
            for j in range(i + 1, n):
                if seq[i] > seq[j]:
                    inversions += 1

        # If there are more negative numbers than positive numbers, 
        # it's better to make more numbers negative
        if negative_count > n // 2:
            return inversions - (negative_count - (n - negative_count))
        else:
            return inversions - (n - negative_count - negative_count)

