from typing import List

class Solution:
    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        parent = list(range(n))

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        # Group nodes by their usage
        groups = {}
        for i, u in enumerate(usage):
            if u not in groups:
                groups[u] = []
            groups[u].append(i)

        # Initialize the maximum possible f
        max_f = 0

        # Iterate over each usage group
        for group in groups.values():
            # Initialize the count of nodes in the current group
            count = len(group)
            # Initialize the set of nodes in the current group
            node_set = set(group)

            # Iterate over each node in the current group
            for node in group:
                # Iterate over each edge
                for edge in edges:
                    # If the edge connects two nodes in the current group
                    if edge[0] in node_set and edge[1] in node_set:
                        # Union the two nodes
                        union(edge[0], edge[1])

            # Count the number of connected components in the current group
            connected_components = len(set(find(node) for node in group))

            # Update the maximum possible f
            max_f = max(max_f, count - connected_components)

        return max_f
